// Simulation Helper Functions
export const resolveDID = async (did: string): Promise<string> => {
  // Simulate network delay
  await new Promise(r => setTimeout(r, 800));
  if (did.startsWith('did:ion:')) {
    // Deterministic mock resolution
    return `0x${did.slice(8, 16)}...Resolved`;
  }
  throw new Error("Invalid DID format");
};

export const formatAddress = (addr: string) => {
  if (addr.length < 10) return addr;
  return `${addr.slice(0, 6)}...${addr.slice(-4)}`;
};

import React from 'react';
import { LayoutDashboard, Wallet, Fingerprint, Users, Settings, LogOut } from 'lucide-react';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  disconnect: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, disconnect }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Overview', icon: LayoutDashboard },
    { id: 'wallet', label: 'Wallet & Pay', icon: Wallet },
    { id: 'identity', label: 'Identity (DID)', icon: Fingerprint },
    { id: 'multisig', label: 'Governance', icon: Users },
  ];

  return (
    <div className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col h-full fixed left-0 top-0 hidden md:flex">
      <div className="p-6 border-b border-slate-800">
        <h1 className="text-2xl font-bold bg-gradient-to-r from-indigo-400 to-cyan-400 bg-clip-text text-transparent">
          IDQ | Soul
        </h1>
        <p className="text-xs text-slate-500 mt-1">Identity-Native Wallet</p>
      </div>

      <nav className="flex-1 p-4 space-y-2">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
