import React, { useState } from 'react';
import { Token, Activity } from '../types';
import { CreditCard, Send, RefreshCw, ArrowUpRight, ArrowDownLeft, Scan } from 'lucide-react';
import { resolveDID, formatAddress } from '../services/mockChain';

interface WalletProps {
  tokens: Token[];
  activities: Activity[];
  onAddFunds: (amount: number, symbol: string) => void;
  onSend: (to: string, amount: number, symbol: string) => Promise<void>;
}

export const WalletPage: React.FC<WalletProps> = ({ tokens, activities, onAddFunds, onSend }) => {
  const [isStripeModalOpen, setStripeModalOpen] = useState(false);
  const [recipient, setRecipient] = useState('');
  const [sendAmount, setSendAmount] = useState('');
  const [selectedToken, setSelectedToken] = useState('USDC');
  const [isResolving, setIsResolving] = useState(false);
  const [resolvedAddress, setResolvedAddress] = useState<string | null>(null);

  const handleResolve = async (val: string) => {
    setRecipient(val);
    setResolvedAddress(null);
    if (val.startsWith('did:ion:')) {
      setIsResolving(true);
      try {
        const addr = await resolveDID(val);
        setResolvedAddress(addr);
      } catch (e) {
        // quiet fail for typing
      } finally {
        setIsResolving(false);
      }
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!recipient || !sendAmount) return;
    await onSend(recipient, parseFloat(sendAmount), selectedToken);
    setRecipient('');
    setSendAmount('');
    setResolvedAddress(null);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in">
      {/* Left Column: Balances & Actions */}
      <div className="lg:col-span-2 space-y-6">
        <h2 className="text-3xl font-bold text-white">Assets</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {tokens.map((token) => (
                <div key={token.symbol} className="bg-slate-800/50 border border-slate-700 rounded-xl p-6 flex items-center justify-between hover:bg-slate-800 transition-colors">
                    <div className="flex items-center space-x-4">
                        <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-xl">
                            {token.icon}
                        </div>
                        <div>
                            <h3 className="font-bold text-white">{token.name}</h3>
                            <p className="text-sm text-slate-400">{token.symbol}</p>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className="text-xl font-mono font-bold text-white">{token.balance.toLocaleString()}</p>
                        <p className="text-xs text-slate-500">
                             ≈ ${(token.balance * (token.symbol === 'ETH' ? 3000 : token.symbol === 'SOUL' ? 1.5 : 1)).toLocaleString()}
                        </p>
                    </div>
                </div>
            ))}
        </div>

        {/* Action Buttons */}
        <div className="flex space-x-4">
            <button 
                onClick={() => setStripeModalOpen(true)}
                className="flex-1 bg-indigo-600 hover:bg-indigo-500 text-white py-4 rounded-xl font-semibold flex items-center justify-center space-x-2 transition-all shadow-lg shadow-indigo-900/20"
            >
                <CreditCard size={20} />
                <span>Buy with Card</span>
            </button>
            <button className="flex-1 bg-slate-700 hover:bg-slate-600 text-white py-4 rounded-xl font-semibold flex items-center justify-center space-x-2 transition-all">
                <ArrowDownLeft size={20} />
                <span>Receive</span>
            </button>
        </div>

        {/* Send Form */}
        <div className="bg-slate-800/50 border border-slate-700 rounded-xl p-6">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center">
                <Send className="mr-2 text-indigo-400" size={18} />
                Send to Identity
            </h3>
            <form onSubmit={handleSend} className="space-y-4">
                <div>
                    <label className="block text-xs font-medium text-slate-400 mb-1">Recipient (DID or Address)</label>
                    <div className="relative">
                        <input 
                            type="text" 
                            value={recipient}
                            onChange={(e) => handleResolve(e.target.value)}
                            placeholder="did:ion:..."
                            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 transition-colors"
                        />
                        {isResolving && (
                            <div className="absolute right-3 top-3">
                                <RefreshCw className="animate-spin text-indigo-400" size={18} />
                            </div>
                        )}
                        <button type="button" className="absolute right-10 top-2 p-1.5 text-slate-400 hover:text-white">
                            <Scan size={18} />
                        </button>
                    </div>
                    {resolvedAddress && (
                        <p className="text-xs text-green-400 mt-1 flex items-center">
                            <Scan size={12} className="mr-1" />
                            Resolved: {resolvedAddress}
                        </p>
                    )}
                </div>

                <div className="flex space-x-4">
                    <div className="flex-1">
                        <label className="block text-xs font-medium text-slate-400 mb-1">Amount</label>
                        <input 
                            type="number" 
                            value={sendAmount}
                            onChange={(e) => setSendAmount(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                            placeholder="0.00"
                        />
                    </div>
                    <div className="w-1/3">
                        <label className="block text-xs font-medium text-slate-400 mb-1">Asset</label>
                        <select 
                            value={selectedToken}
                            onChange={(e) => setSelectedToken(e.target.value)}
                            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                        >
                            {tokens.map(t => <option key={t.symbol} value={t.symbol}>{t.symbol}</option>)}
                        </select>
                    </div>
                </div>

                <button 
                    type="submit" 
                    disabled={!recipient || !sendAmount}
                    className="w-full bg-gradient-to-r from-indigo-600 to-cyan-600 hover:from-indigo-500 hover:to-cyan-500 text-white font-bold py-3 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    Sign & Send
                </button>
            </form>
        </div>
      </div>

      {/* Right Column: Activity */}
      <div className="space-y-6">
        <h3 className="text-xl font-bold text-white">Recent Activity</h3>
        <div className="bg-slate-800/30 rounded-xl p-4 border border-slate-800 h-[500px] overflow-y-auto">
            {activities.length === 0 ? (
                <p className="text-slate-500 text-center mt-10">No activity yet</p>
            ) : (
                <div className="space-y-4">
                    {activities.map((activity) => (
                        <div key={activity.id} className="flex items-start space-x-3 pb-4 border-b border-slate-800 last:border-0">
                            <div className={`p-2 rounded-lg mt-1 ${
                                activity.type === 'Transfer' ? 'bg-indigo-500/10 text-indigo-400' : 
                                activity.type === 'Mint' ? 'bg-green-500/10 text-green-400' :
                                'bg-amber-500/10 text-amber-400'
                            }`}>
                                {activity.type === 'Transfer' ? <ArrowUpRight size={16} /> :
                                 activity.type === 'Mint' ? <ArrowDownLeft size={16} /> :
                                 <RefreshCw size={16} />}
                            </div>
                            <div>
                                <p className="text-sm font-medium text-slate-200">{activity.detail}</p>
                                <p className="text-xs text-slate-500">{new Date(activity.timestamp).toLocaleString()}</p>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
      </div>

      {/* Mock Stripe Modal */}
      {isStripeModalOpen && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50">
              <div className="bg-white rounded-xl p-8 max-w-md w-full relative">
                  <h3 className="text-2xl font-bold text-slate-900 mb-4 flex items-center">
                    <CreditCard className="mr-2 text-indigo-600" /> Stripe Checkout
                  </h3>
                  <p className="text-slate-600 mb-6">Mocking Fiat-to-Crypto On-Ramp. Purchasing 100 USDC.</p>

                  <div className="bg-slate-100 p-4 rounded-lg mb-6 border border-slate-200">
                      <div className="flex justify-between mb-2">
                          <span className="text-slate-600">Amount</span>
                          <span className="font-bold text-slate-900">$100.00 USD</span>
                      </div>
                      <div className="flex justify-between">
                          <span className="text-slate-600">Receive</span>
                          <span className="font-bold text-slate-900">100.00 USDC</span>
                      </div>
                  </div>

                  <div className="flex space-x-3">
                      <button 
                        onClick={() => setStripeModalOpen(false)}
                        className="flex-1 py-3 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
                      >
                          Cancel
                      </button>
                      <button 
                        onClick={() => {
                            onAddFunds(100, 'USDC');
                            setStripeModalOpen(false);
                        }}
                        className="flex-1 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-bold transition-colors"
                      >
                          Pay Now
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Proposal, User } from '../types';
import { Users, FileText, Check, Play, Clock, AlertCircle } from 'lucide-react';

interface MultisigProps {
  proposals: Proposal[];
  user: User;
  onApprove: (id: string) => void;
  onExecute: (id: string) => void;
  onCreateProposal: (data: Partial<Proposal>) => void;
}

export const MultisigPage: React.FC<MultisigProps> = ({ proposals, user, onApprove, onExecute, onCreateProposal }) => {
  const [isModalOpen, setModalOpen] = useState(false);
  const [newProp, setNewProp] = useState({ title: '', to: '', amount: 0, symbol: 'ETH', description: '' });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onCreateProposal(newProp);
    setModalOpen(false);
    setNewProp({ title: '', to: '', amount: 0, symbol: 'ETH', description: '' });
  };

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-white">Governance</h2>
          <p className="text-slate-400 mt-1">Managed by DID Guardians • Threshold 3/5</p>
        </div>
        <button 
          onClick={() => setModalOpen(true)}
          className="flex items-center space-x-2 bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-3 rounded-lg transition-colors shadow-lg shadow-indigo-900/20 font-semibold"
        >
          <FileText size={18} />
          <span>New Proposal</span>
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
            <h4 className="text-slate-400 text-sm font-medium uppercase">Guardians</h4>
            <div className="mt-2 flex items-center space-x-2">
                <Users className="text-indigo-400" />
                <span className="text-2xl font-bold text-white">5</span>
            </div>
        </div>
        <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
            <h4 className="text-slate-400 text-sm font-medium uppercase">Threshold</h4>
            <div className="mt-2 flex items-center space-x-2">
                <Check className="text-green-400" />
                <span className="text-2xl font-bold text-white">3 Required</span>
            </div>
        </div>
        <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-xl">
            <h4 className="text-slate-400 text-sm font-medium uppercase">Treasury Value</h4>
            <div className="mt-2 flex items-center space-x-2">
                <span className="text-2xl font-bold text-white">$4,250.00</span>
            </div>
        </div>
      </div>

      {/* Proposals List */}
      <div className="space-y-4">
        <h3 className="text-xl font-bold text-white">Active Proposals</h3>
        {proposals.length === 0 && <p className="text-slate-500">No active proposals.</p>}

        {proposals.map((prop) => {
            const progress = (prop.approvals / prop.threshold) * 100;
            const canExecute = prop.approvals >= prop.threshold;

            return (
                <div key={prop.id} className="bg-slate-800/30 border border-slate-700 rounded-xl p-6 hover:border-slate-600 transition-all">
                    <div className="flex flex-col md:flex-row justify-between md:items-center mb-4 gap-4">
                        <div className="flex items-start space-x-4">
                            <div className={`p-3 rounded-lg ${
                                prop.status === 'Executed' ? 'bg-green-500/20 text-green-400' : 'bg-amber-500/20 text-amber-400'
                            }`}>
                                <FileText size={24} />
                            </div>
                            <div>
                                <h4 className="text-lg font-bold text-white">{prop.title}</h4>
                                <p className="text-sm text-slate-400">{prop.description}</p>
                                <div className="flex items-center space-x-4 mt-2 text-xs font-mono text-slate-500">
                                    <span>ID: {prop.id}</span>
                                    <span>To: {prop.to.slice(0, 10)}...</span>
                                    <span className="text-indigo-400 bg-indigo-900/20 px-2 py-0.5 rounded">{prop.amount} {prop.symbol}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center space-x-3">
                            {prop.status === 'Pending' && !canExecute && (
                                <button 
                                    onClick={() => onApprove(prop.id)}
                                    className="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-sm font-medium transition-colors"
                                >
                                    Approve (Sign)
                                </button>
                            )}

                            {prop.status === 'Pending' && canExecute && (
                                <button 
                                    onClick={() => onExecute(prop.id)}
                                    className="px-4 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg text-sm font-medium transition-colors flex items-center animate-pulse"
                                >
                                    <Play size={14} className="mr-1" /> Execute
                                </button>
                            )}

                            {prop.status === 'Executed' && (
                                <span className="px-4 py-2 bg-green-500/10 text-green-400 rounded-lg text-sm font-medium border border-green-500/20">
