                        <span>{prop.approvals} of {prop.threshold} approvals</span>
                        <span className="flex items-center"><Clock size={12} className="mr-1" /> Ends in 2 days</span>
                    </div>
                </div>
            );
        })}
      </div>

        {/* New Proposal Modal */}
      {isModalOpen && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50">
              <div className="bg-slate-900 border border-slate-700 rounded-xl p-8 max-w-md w-full">
                  <h3 className="text-xl font-bold text-white mb-6">Create Proposal</h3>
                  <form onSubmit={handleSubmit} className="space-y-4">
                      <div>
                          <label className="block text-xs font-medium text-slate-400 mb-1">Title</label>
                          <input required type="text" value={newProp.title} onChange={e => setNewProp({...newProp, title: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-white" />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 mb-1">Description</label>
                          <textarea required value={newProp.description} onChange={e => setNewProp({...newProp, description: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-white" />
                      </div>
                      <div className="flex space-x-2">
                          <div className="flex-1">
                              <label className="block text-xs font-medium text-slate-400 mb-1">Amount</label>
                              <input required type="number" value={newProp.amount} onChange={e => setNewProp({...newProp, amount: parseFloat(e.target.value)})} className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-white" />
                          </div>
                          <div className="w-24">
                              <label className="block text-xs font-medium text-slate-400 mb-1">Token</label>
                              <select value={newProp.symbol} onChange={e => setNewProp({...newProp, symbol: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-white">
                                  <option value="ETH">ETH</option>
                                  <option value="USDC">USDC</option>
                              </select>
                          </div>
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 mb-1">Recipient (DID/Address)</label>
                          <input required type="text" value={newProp.to} onChange={e => setNewProp({...newProp, to: e.target.value})} className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-white" />
                      </div>
                      <div className="flex space-x-3 mt-6">
                          <button type="button" onClick={() => setModalOpen(false)} className="flex-1 py-2 text-slate-400 hover:bg-slate-800 rounded-lg">Cancel</button>
                          <button type="submit" className="flex-1 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-bold">Create</button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
