// Simple Error Boundary for React 19 compliance
class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { hasError: boolean }> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() { return { hasError: true }; }
  render() {
    if (this.state.hasError) return <div className="p-8 text-red-500">Critical Error: App Crashed. Check Console.</div>;
    return this.props.children;
  }
}

const App: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');

  // App State simulating Blockchain State
  const [tokens, setTokens] = useState<Token[]>(INITIAL_TOKENS);
  const [proposals, setProposals] = useState<Proposal[]>(INITIAL_PROPOSALS);
  const [activities, setActivities] = useState<Activity[]>([]);

  // Simulate Connecting to WalletConnect / MetaMask
  const handleConnect = () => {
    setIsConnecting(true);
    setTimeout(() => {
      setIsConnected(true);
      setIsConnecting(false);
      setActiveTab('dashboard');
    }, 1500);
  };

  // 2. Buy with Stripe (Mock)
  const handleAddFunds = (amount: number, symbol: string) => {
    setTokens(prev => prev.map(t => 
      t.symbol === symbol ? { ...t, balance: t.balance + amount } : t
    ));
    const newActivity: Activity = {
      id: Date.now().toString(),
      type: 'Mint',
      detail: `Purchased ${amount} ${symbol} via Stripe`,
      timestamp: new Date().toISOString()
    };
    setActivities([newActivity, ...activities]);
  };

  // 3. Send to DID
  const handleSend = async (to: string, amount: number, symbol: string) => {
    // Optimistic Update
    setTokens(prev => prev.map(t => 
      t.symbol === symbol ? { ...t, balance: t.balance - amount } : t
    ));
    const newActivity: Activity = {
      id: Date.now().toString(),
      type: 'Transfer',
      detail: `Sent ${amount} ${symbol} to ${to.startsWith('did:') ? 'DID' : 'Addr'}...`,
      timestamp: new Date().toISOString()
    };
    setActivities([newActivity, ...activities]);
  };

  // 6,7,8 Governance Actions
  const handleCreateProposal = (data: Partial<Proposal>) => {
    const newProp: Proposal = {
      id: `prop-${Date.now()}`,
      title: data.title || 'Untitled',
      description: data.description || '',
      to: data.to || '',
      amount: data.amount || 0,
      symbol: data.symbol || 'ETH',
      approvals: 0,
      threshold: 3,
      status: 'Pending',
      timestamp: new Date().toISOString()
    };
    setProposals([newProp, ...proposals]);
  };

  const handleApprove = (id: string) => {
    setProposals(prev => prev.map(p => 
      p.id === id ? { ...p, approvals: p.approvals + 1 } : p
    ));
  };

  const handleExecute = (id: string) => {
    setProposals(prev => prev.map(p => 
      p.id === id ? { ...p, status: 'Executed' } : p
    ));
    const prop = proposals.find(p => p.id === id);
    if (prop) {
       // Deduct funds if executed
       setTokens(prev => prev.map(t => 
         t.symbol === prop.symbol ? { ...t, balance: t.balance - prop.amount } : t
       ));
       setActivities([{
         id: Date.now().toString(),
         type: 'Execution',
         detail: `Executed Proposal: ${prop.title}`,
         timestamp: new Date().toISOString()
       }, ...activities]);
    }
  };

  if (!isConnected) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-4">
        <div className="max-w-md w-full text-center space-y-8 animate-fade-in">
          <div className="mb-8">
            <h1 className="text-5xl font-bold bg-gradient-to-r from-indigo-400 via-purple-400 to-cyan-400 bg-clip-text text-transparent mb-2">
              IDQ | Soul
            </h1>
            <p className="text-slate-400 text-lg">Identity-Native Wallet Operating System</p>
          </div>

          <div className="bg-slate-900 border border-slate-800 p-8 rounded-2xl shadow-2xl">
            <div className="space-y-4">
               <button 
                  onClick={handleConnect}
                  disabled={isConnecting}
                  className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-4 rounded-xl flex items-center justify-center space-x-3 transition-all disabled:opacity-50 disabled:cursor-not-allowed group"
               >
                 {isConnecting ? (
                   <span className="animate-pulse">Connecting to Network...</span>
                 ) : (
                   <>
                     <Wallet className="group-hover:scale-110 transition-transform" />
                     <span>Connect MetaMask</span>
                   </>
                 )}
               </button>

               <button 
                  onClick={handleConnect}
                  disabled={isConnecting}
                  className="w-full bg-slate-800 hover:bg-slate-700 text-white font-bold py-4 rounded-xl flex items-center justify-center space-x-3 transition-all border border-slate-700"
               >
                 <QrCode />
                 <span>WalletConnect (QR)</span>
               </button>
            </div>

            <p className="mt-6 text-xs text-slate-500">
              By connecting, you agree to sign with your DID key (ION network).
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 font-sans selection:bg-indigo-500/30">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} disconnect={() => setIsConnected(false)} />

      <main className="md:ml-64 p-4 md:p-8 min-h-screen">
        <div className="max-w-6xl mx-auto mt-16 md:mt-0">
          {/* Mobile Header */}
          <div className="md:hidden fixed top-0 left-0 right-0 bg-slate-900 border-b border-slate-800 p-4 z-40 flex justify-between items-center">
             <h1 className="font-bold text-lg text-white">IDQ | Soul</h1>
             <button onClick={() => setIsConnected(false)} className="text-xs text-slate-400">Exit</button>
          </div>

          <ErrorBoundary>
            {activeTab === 'dashboard' && (
              <div className="space-y-8 animate-fade-in">
                 <div className="bg-gradient-to-r from-indigo-900 to-purple-900 rounded-3xl p-8 md:p-12 text-center md:text-left relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-full h-full bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    <div className="relative z-10">
                      <h2 className="text-3xl md:text-5xl font-bold text-white mb-4">Welcome back, {INITIAL_USER.name}</h2>
                      <p className="text-indigo-200 text-lg max-w-2xl">
                        Your Soul Wallet is active. You have <strong className="text-white">{proposals.filter(p => p.status === 'Pending').length} pending proposals</strong> requiring your DID signature.
                      </p>
                      <div className="mt-8 flex flex-wrap gap-4 justify-center md:justify-start">
                        <button onClick={() => setActiveTab('wallet')} className="bg-white text-indigo-900 px-6 py-3 rounded-full font-bold hover:bg-indigo-50 transition-colors">
                          Add Funds
                        </button>
                        <button onClick={() => setActiveTab('multisig')} className="bg-indigo-700/50 text-white border border-indigo-400/30 px-6 py-3 rounded-full font-bold hover:bg-indigo-700 transition-colors">
                          Review Proposals
                        </button>
                      </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    {INITIAL_SBTS.map(sbt => (
                       <div key={sbt.id} className="bg-slate-900 border border-slate-800 p-4 rounded-xl flex items-center space-x-3">
                          <div className="w-2 h-2 rounded-full bg-green-400"></div>
                          <div>
                            <p className="text-xs text-slate-500 uppercase font-bold">{sbt.type}</p>
                            <p className="font-semibold">{sbt.name}</p>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>
            )}

            {activeTab === 'wallet' && (
              <WalletPage 
                tokens={tokens} 
                activities={activities}
                onAddFunds={handleAddFunds}
                onSend={handleSend}
              />
            )}

            {activeTab === 'identity' && (
              <Identity user={INITIAL_USER} sbts={INITIAL_SBTS} />
            )}

            {activeTab === 'multisig' && (
              <MultisigPage 
                proposals={proposals}
                user={INITIAL_USER}
                onApprove={handleApprove}
                onExecute={handleExecute}
                onCreateProposal={handleCreateProposal}
              />
            )}
          </ErrorBoundary>
        </div>
      </main>
    </div>
  );
};

export default App;

