import React, { useState, useEffect, useRef } from "react";
import { createRoot } from "react-dom/client";
import { 
  Wallet, 
  Send, 
  User, 
  Shield, 
  Plus, 
  Search, 
  Activity, 
  CreditCard, 
  Key, 
  CheckCircle, 
  XCircle, 
  Loader2, 
  QrCode, 
  Copy, 
  Eye, 
  EyeOff, 
  RefreshCw,
  Server,
  AlertTriangle
} from "lucide-react";
import jsQR from "jsqr";
import { ethers } from "ethers";
import QRCode from "react-qr-code";

// --- ERROR BOUNDARY ---

interface ErrorBoundaryProps {
  children: React.ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-red-50 p-4">
          <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-red-100">
            <div className="flex items-center gap-3 text-red-600 mb-4">
              <AlertTriangle size={32} />
              <h1 className="text-xl font-bold">Something went wrong</h1>
            </div>
            <p className="text-slate-600 mb-4">The application crashed. Please refresh the page.</p>
            <div className="bg-slate-100 p-3 rounded-lg overflow-auto max-h-40 mb-6">
              <code className="text-xs font-mono text-slate-700">
                {this.state.error?.toString()}
              </code>
            </div>
            <button 
              onClick={() => window.location.reload()}
              className="w-full py-3 bg-red-600 text-white rounded-lg font-medium hover:bg-red-700 transition-colors"
            >
              Refresh Page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

// --- MOCK BACKEND SIMULATION ---

const SIMULATION_DELAY = 600; // ms to simulate network latency

const mockDb = {
  getBalance: (addr: string) => {
    return localStorage.getItem(`mock_bal_${addr.toLowerCase()}`) || "0";
  },
  setBalance: (addr: string, amount: string) => {
    localStorage.setItem(`mock_bal_${addr.toLowerCase()}`, amount);
  },
  getMultisig: (address: string) => {
    const data = localStorage.getItem(`mock_ms_${address.toLowerCase()}`);
    return data ? JSON.parse(data) : null;
  },
  saveMultisig: (address: string, data: any) => {
    localStorage.setItem(`mock_ms_${address.toLowerCase()}`, JSON.stringify(data));
  }
};

const mockApiCall = async (endpoint: string, params: any) => {
  console.log(`[Mock API] Request to ${endpoint}`, params);
  await new Promise(resolve => setTimeout(resolve, SIMULATION_DELAY));

  try {
    // --- Token Logic ---
    if (endpoint === '/api/balance/token') {
      const bal = mockDb.getBalance(params.addr);
      return { balance: bal }; 
    }

    if (endpoint === '/api/mintToken') {
      const current = BigInt(mockDb.getBalance(params.to));
      const amount = BigInt(params.amount);
      mockDb.setBalance(params.to, (current + amount).toString());
      return { result: 'success' };
    }

    if (endpoint === '/api/send') {
      const fromBal = BigInt(mockDb.getBalance(params.from));
      const amount = BigInt(params.amount);

      if (fromBal < amount) {
        return { result: 'error', message: 'Insufficient balance' };
      }

      const toBal = BigInt(mockDb.getBalance(params.to));
      mockDb.setBalance(params.from, (fromBal - amount).toString());
      mockDb.setBalance(params.to, (toBal + amount).toString());
      return { result: 'success' };
    }

    // --- DID Logic ---
    if (endpoint === '/api/create') {
      const did = `did:ion:test:${params.addr.substring(0, 8)}...`;
      localStorage.setItem(`mock_did_${did}`, JSON.stringify({
        id: did,
        controller: params.addr,
        verificationMethod: [{
          id: "#key-1",
          type: "EcdsaSecp256k1VerificationKey2019",
          controller: did,
          publicKeyHex: "02..." 
        }]
      }));
      return { result: 'success', id: did };
    }

    if (endpoint === '/api/resolve') {
      const doc = localStorage.getItem(`mock_did_${params.uri}`);
      if (doc) return { result: JSON.parse(doc) };
      return { result: { 
        id: params.uri, 
        status: "not_found_in_mock_db", 
        note: "This is a simulated resolution." 
      }};
    }

    // --- MultiSig Logic ---
    if (endpoint === '/api/factory/create') {
      const mockAddr = "0x" + Array(40).fill(0).map(() => Math.floor(Math.random()*16).toString(16)).join("");
      const walletData = {
        address: mockAddr,
        name: params.name,
        owners: params.owners,
        required: parseInt(params.required),
        txCount: 0,
        transactions: {}
      };
      mockDb.saveMultisig(mockAddr, walletData);
      return { result: 'success', address: mockAddr };
    }

    if (endpoint.startsWith('/api/wallet/')) {
      const action = endpoint.split('/').pop();
      const ms = mockDb.getMultisig(params.address);

      if (!ms) return { result: 'error', message: 'Wallet not found' };

      if (action === 'submit') {
        const txId = ms.txCount++;
        ms.transactions[txId] = {
          to: params.to,
          value: params.value,
          data: params.data,
          executed: false,
          confirmations: 0
        };
        mockDb.saveMultisig(params.address, ms);
        return { result: 'success', txId };
      }

      if (action === 'approve') {
        return { result: 'success' };
      }

      if (action === 'execute') {
         if (ms.transactions[params.txId]) {
           ms.transactions[params.txId].executed = true;
           mockDb.saveMultisig(params.address, ms);
         }
         return { result: 'success' };
      }
    }

    return { result: 'error', message: 'Unknown endpoint' };
  } catch (e) {
    console.error("Mock API Error", e);
    return { result: 'error', message: 'Simulation failed' };
  }
};

const postWithQuery = async (endpoint: string, params: Record<string, any>) => {
  return mockApiCall(endpoint, params);
};

const getWithQuery = async (endpoint: string, params: Record<string, any>) => {
  return mockApiCall(endpoint, params);
};

// --- Components ---

const Button = ({ children, onClick, variant = "primary", className = "", isLoading = false }: any) => {
  const baseStyle = "px-4 py-2 rounded-lg font-medium transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 shadow-md hover:shadow-lg",
    secondary: "bg-white text-slate-700 border border-slate-200 hover:bg-slate-50 hover:border-slate-300",
    danger: "bg-red-50 text-red-600 hover:bg-red-100 border border-red-200",
    ghost: "text-slate-600 hover:bg-slate-100"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={isLoading}
      className={`${baseStyle} ${variants[variant as keyof typeof variants]} ${className}`}
    >
      {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
      {children}
    </button>
  );
};

const Input = ({ label, rightElement, ...props }: any) => (
  <div className="flex flex-col gap-1.5">
    {label && <label className="text-sm font-medium text-slate-700">{label}</label>}
    <div className="relative">
      <input 
        className={`px-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-colors w-full ${rightElement ? 'pr-10' : ''}`}
        {...props}
      />
      {rightElement && (
        <div className="absolute right-2 top-1/2 -translate-y-1/2 z-10 flex items-center justify-center">
          {rightElement}
        </div>
      )}
    </div>
  </div>
);

const Card = ({ title, icon: Icon, children, className = "" }: any) => (
  <div className={`bg-white rounded-xl border border-slate-200 shadow-sm p-6 ${className}`}>
    {(title || Icon) && (
      <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
        {Icon && <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg"><Icon size={20} /></div>}
        <h2 className="text-lg font-semibold text-slate-900">{title}</h2>
      </div>
    )}
    {children}
  </div>
);

const QRScannerModal = ({ onScan, onClose }: { onScan: (data: string) => void, onClose: () => void }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let stream: MediaStream | null = null;
    let animationId: number;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute("playsinline", "true"); 
          videoRef.current.play();
          requestAnimationFrame(tick);
        }
      } catch (err) {
        console.error("Error accessing camera", err);
        alert("Could not access camera. Please ensure you have granted camera permissions.");
        onClose();
      }
    };

    const tick = () => {
      if (videoRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
        if (canvasRef.current) {
          const canvas = canvasRef.current;
          const video = videoRef.current;

          if (canvas.width !== video.videoWidth || canvas.height !== video.videoHeight) {
             canvas.width = video.videoWidth;
             canvas.height = video.videoHeight;
          }

          const ctx = canvas.getContext("2d");
          if (ctx) {
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
            const code = jsQR(imageData.data, imageData.width, imageData.height, {
              inversionAttempts: "dontInvert",
            });
            if (code && code.data) {
              onScan(code.data);
              return; // Stop scanning loop
            }
          }
        }
      }
      animationId = requestAnimationFrame(tick);
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
      cancelAnimationFrame(animationId);
    };
  }, [onScan, onClose]);

  return (
    <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-4 animate-in fade-in duration-200">
       <div className="relative w-full max-w-sm aspect-[3/4] bg-black rounded-2xl overflow-hidden border border-slate-800 shadow-2xl">
          <video ref={videoRef} className="w-full h-full object-cover opacity-80" muted />
          <canvas ref={canvasRef} className="hidden" />

          {/* Scanning Overlay */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-64 h-64 border-2 border-indigo-500/80 rounded-lg relative">
                  <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-500 -mt-1 -ml-1"></div>
                  <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-500 -mt-1 -mr-1"></div>
                  <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-500 -mb-1 -ml-1"></div>
                  <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-500 -mb-1 -mr-1"></div>
                  {/* Scan line animation */}
                  <div className="absolute left-0 right-0 h-0.5 bg-indigo-500/50 animate-[scan_2s_ease-in-out_infinite] top-0 shadow-[0_0_8px_rgba(99,102,241,0.8)]"></div>
              </div>
          </div>

          <div className="absolute bottom-8 left-0 right-0 text-center text-white/90 font-medium px-4">
              Align QR code within the frame
          </div>
       </div>
       <button 
        onClick={onClose} 
        className="mt-8 px-8 py-3 bg-slate-800 text-white rounded-full font-semibold hover:bg-slate-700 transition-colors border border-slate-700"
       >
         Close Scanner
       </button>
       <style>{`
         @keyframes scan {
           0% { top: 0; opacity: 0; }
           10% { opacity: 1; }
           90% { opacity: 1; }
           100% { top: 100%; opacity: 0; }
         }
       `}</style>
    </div>
  )
};

const QRDisplayModal = ({ value, title, onClose }: any) => (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200" onClick={onClose}>
       <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-xs flex flex-col items-center gap-4 animate-in zoom-in-95 duration-200" onClick={e => e.stopPropagation()}>
          <h3 className="text-lg font-bold text-slate-900">{title || "QR Code"}</h3>
          <div className="p-4 rounded-xl border border-slate-100 shadow-sm bg-white">
             <QRCode value={value} size={200} style={{ height: "auto", maxWidth: "100%", width: "100%" }} viewBox={`0 0 256 256`} />
          </div>
          <div className="w-full bg-slate-50 p-3 rounded-lg border border-slate-200">
            <p className="text-xs text-center text-slate-500 font-mono break-all">{value}</p>
          </div>
          <Button onClick={onClose} className="w-full">Close</Button>
       </div>
    </div>
);

const WalletGenerator = ({ onGenerate }: { onGenerate?: (address: string) => void }) => {
  const [wallet, setWallet] = useState<{address: string, privateKey: string, mnemonic?: string} | null>(null);
  const [showPrivate, setShowPrivate] = useState(false);
  const [showMnemonic, setShowMnemonic] = useState(false);
  const [copied, setCopied] = useState<string | null>(null);
  const [showQr, setShowQr] = useState(false);
  const [isGenerating, setIsGenerating] = useState(true);

  const generate = () => {
    try {
      const w = ethers.Wallet.createRandom();
      const newWallet = {
        address: w.address,
        privateKey: w.privateKey,
        mnemonic: w.mnemonic?.phrase
      };
      setWallet(newWallet);
      setShowPrivate(false);
      setShowMnemonic(false);
      if (onGenerate) onGenerate(newWallet.address);
    } catch (e) {
      console.error("Error generating wallet", e);
    } finally {
      setIsGenerating(false);
    }
  };

  useEffect(() => {
    // Auto-generate on mount to show wallet immediately
    const t = setTimeout(() => generate(), 100);
    return () => clearTimeout(t);
  }, []);

  const copyToClipboard = (text: string, key: string) => {
    navigator.clipboard.writeText(text);
    setCopied(key);
    setTimeout(() => setCopied(null), 2000);
  };

  if (isGenerating && !wallet) {
    return (
        <Card title="New Wallet" icon={CreditCard}>
