                   <button 
                     onClick={() => copyToClipboard(wallet.address, 'addr')}
                     className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                     title="Copy Address"
                   >
                     {copied === 'addr' ? <CheckCircle size={20} className="text-green-600" /> : <Copy size={20} />}
                   </button>
                </div>
             </div>

             <div className="group">
                <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1 block">Private Key</label>
                <div className="flex gap-2">
                   <code className="flex-1 p-3 bg-slate-50 border border-slate-200 rounded-lg font-mono text-sm break-all text-slate-700 relative overflow-hidden">
                     <span className={showPrivate ? "" : "blur-sm select-none"}>
                       {wallet.privateKey}
                     </span>
                     {!showPrivate && <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-xs font-medium">Click eye to reveal</div>}
                   </code>
                   <button 
