                       <span className={showMnemonic ? "" : "blur-sm select-none"}>
                         {wallet.mnemonic}
                       </span>
                       {!showMnemonic && <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-xs font-medium">Click eye to reveal</div>}
                    </code>
                    <button 
                     onClick={() => setShowMnemonic(!showMnemonic)}
                     className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors h-fit"
                     title={showMnemonic ? "Hide Mnemonic" : "Show Mnemonic"}
                   >
                     {showMnemonic ? <EyeOff size={20} /> : <Eye size={20} />}
                   </button>
                   <button 
                     onClick={() => copyToClipboard(wallet.mnemonic!, 'phrase')}
                     className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors h-fit"
                     title="Copy Mnemonic"
                   >
                     {copied === 'phrase' ? <CheckCircle size={20} className="text-green-600" /> : <Copy size={20} />}
                   </button>
                  </div>
              </div>
             )}
