    </>
  );
};

// --- Feature Sections ---

const Dashboard = () => {
  const [address, setAddress] = useState("");
  const [balance, setBalance] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [mintLoading, setMintLoading] = useState(false);
  const [mintAmount, setMintAmount] = useState("100");

  const checkBalance = async () => {
    if (!address) return;
    setLoading(true);
    try {
      const res = await getWithQuery('/api/balance/token', { addr: address });
      // Balance comes as string from mock backend
      const hex = res.balance;
      // Convert to string via BigInt
      setBalance(BigInt(hex).toString());
    } catch (e) {
      console.error(e);
      setBalance("Error");
    }
    setLoading(false);
  };

  const mintTokens = async () => {
    if (!address) return;
    setMintLoading(true);
    try {
      await postWithQuery('/api/mintToken', { to: address, amount: mintAmount });
      await checkBalance();
    } catch (e) {
      console.error(e);
    }
    setMintLoading(false);
  };

  return (
    <div className="space-y-6">
      <WalletGenerator onGenerate={(addr) => setAddress(addr)} />

      <Card title="Wallet Balance" icon={Wallet}>
        <div className="flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <Input 
              label="Wallet Address" 
              placeholder="0x..." 
              value={address} 
              onChange={(e: any) => setAddress(e.target.value)} 
            />
          </div>
          <Button onClick={checkBalance} isLoading={loading} className="w-full md:w-auto">Check Balance</Button>
        </div>

        {balance !== null && (
          <div className="mt-6 p-4 bg-slate-50 rounded-lg border border-slate-100 flex items-center justify-between">
            <span className="text-sm font-medium text-slate-500">Current Balance</span>
            <span className="text-2xl font-bold text-slate-900 break-all">{balance} Tokens</span>
          </div>
        )}
      </Card>

      <Card title="Faucet (Mint Tokens)" icon={Plus}>
        <div className="flex flex-col md:flex-row gap-4 items-end">
           <div className="flex-1 w-full">
            <Input 
              label="Amount (Demo)" 
              type="number"
              value={mintAmount} 
              onChange={(e: any) => setMintAmount(e.target.value)} 
            />
          </div>
          <Button onClick={mintTokens} variant="secondary" isLoading={mintLoading} className="w-full md:w-auto">Mint Tokens (Demo)</Button>
        </div>
      </Card>
    </div>
  );
};

const Transfer = () => {
  const [form, setForm] = useState({ from: "", to: "", amount: "" });
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<{type: 'success' | 'error', msg: string} | null>(null);
  const [scanningField, setScanningField] = useState<'from' | 'to' | null>(null);

  const handleSend = async () => {
    setLoading(true);
    setStatus(null);
    try {
      const res = await postWithQuery('/api/send', { 
        from: form.from, 
        to: form.to, 
        amount: form.amount 
      });
      if (res.result === 'success') {
        setStatus({ type: 'success', msg: 'Transfer successful! (Demo)' });
        setForm({ ...form, amount: "" });
      } else {
        setStatus({ type: 'error', msg: res.message || 'Transfer failed.' });
      }
    } catch (e) {
      setStatus({ type: 'error', msg: 'Network error occurred.' });
    }
    setLoading(false);
  };

  const handleScan = (data: string) => {
    if (scanningField) {
      setForm(prev => ({ ...prev, [scanningField]: data }));
      setScanningField(null);
    }
  };

  const renderScanButton = (field: 'from' | 'to') => (
    <button
      type="button"
      onClick={() => setScanningField(field)}
      className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors"
      title="Scan QR Code"
    >
      <QrCode size={18} />
    </button>
  );

  return (
    <>
      {scanningField && (
        <QRScannerModal 
          onScan={handleScan} 
          onClose={() => setScanningField(null)} 
        />
      )}
      <Card title="Transfer Tokens" icon={Send}>
        <div className="space-y-4">
          <Input 
            label="From Address" 
            placeholder="0x..." 
            value={form.from} 
            onChange={(e: any) => setForm({...form, from: e.target.value})} 
            rightElement={renderScanButton('from')}
          />
          <Input 
            label="To Address" 
            placeholder="0x..." 
            value={form.to} 
            onChange={(e: any) => setForm({...form, to: e.target.value})} 
            rightElement={renderScanButton('to')}
          />
          <Input 
            label="Amount" 
            type="number" 
            value={form.amount} 
            onChange={(e: any) => setForm({...form, amount: e.target.value})} 
          />

          <div className="pt-2">
            <Button onClick={handleSend} isLoading={loading} className="w-full">
              Send Tokens
            </Button>
          </div>

          {status && (
            <div className={`p-3 rounded-lg flex items-center gap-2 ${
              status.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}>
              {status.type === 'success' ? <CheckCircle size={18} /> : <XCircle size={18} />}
              {status.msg}
            </div>
          )}
        </div>
      </Card>
    </>
  );
};

const Identity = () => {
  const [createAddr, setCreateAddr] = useState("");
  const [createdDid, setCreatedDid] = useState<string | null>(null);
  const [createLoading, setCreateLoading] = useState(false);

  const [resolveUri, setResolveUri] = useState("");
  const [resolvedDoc, setResolvedDoc] = useState<any>(null);
  const [resolveLoading, setResolveLoading] = useState(false);

  const handleCreate = async () => {
    setCreateLoading(true);
    try {
      const res = await postWithQuery('/api/create', { addr: createAddr });
      if (res.result === 'success') {
        setCreatedDid(`Success: ${res.id}`);
      } else {
        setCreatedDid("Failed to create DID");
      }
    } catch (e) {
      setCreatedDid("Error creating DID");
    }
    setCreateLoading(false);
  };

  const handleResolve = async () => {
    setResolveLoading(true);
    try {
      const res = await getWithQuery('/api/resolve', { uri: resolveUri });
      setResolvedDoc(res.result);
    } catch (e) {
      setResolvedDoc({ error: "Failed to resolve" });
    }
    setResolveLoading(false);
  };

  return (
    <div className="space-y-6">
      <Card title="Create Digital Identity" icon={User}>
        <div className="flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <Input 
              label="Ethereum Address" 
              placeholder="0x..." 
              value={createAddr} 
              onChange={(e: any) => setCreateAddr(e.target.value)} 
            />
          </div>
          <Button onClick={handleCreate} isLoading={createLoading} className="w-full md:w-auto">Create DID</Button>
        </div>
        {createdDid && (
          <div className="mt-4 p-3 bg-green-50 text-green-700 rounded-lg border border-green-100 break-all">
            {createdDid}
          </div>
        )}
      </Card>

      <Card title="Resolve Identity" icon={Search}>
        <div className="flex flex-col md:flex-row gap-4 items-end mb-4">
          <div className="flex-1 w-full">
            <Input 
              label="DID URI" 
              placeholder="did:ion:..." 
              value={resolveUri} 
              onChange={(e: any) => setResolveUri(e.target.value)} 
            />
          </div>
          <Button variant="secondary" onClick={handleResolve} isLoading={resolveLoading} className="w-full md:w-auto">Resolve</Button>
        </div>
        {resolvedDoc && (
          <div className="bg-slate-900 rounded-lg p-4 overflow-x-auto">
            <pre className="text-xs text-slate-300 font-mono">
              {JSON.stringify(resolvedDoc, null, 2)}
            </pre>
          </div>
        )}
      </Card>
    </div>
  );
};

const MultiSig = () => {
  const [tab, setTab] = useState<'create' | 'interact'>('create');

  // Create State
  const [createName, setCreateName] = useState("");
  const [owners, setOwners] = useState("");
  const [required, setRequired] = useState("1");
  const [createLoading, setCreateLoading] = useState(false);
  const [createStatus, setCreateStatus] = useState("");

  // Interact State
  const [walletAddr, setWalletAddr] = useState("");
  const [txId, setTxId] = useState("");
  const [to, setTo] = useState("");
  const [value, setValue] = useState("0");
  const [data, setData] = useState("0x");
  const [interactLoading, setInteractLoading] = useState(false);
  const [interactStatus, setInteractStatus] = useState("");

  const handleCreate = async () => {
    setCreateLoading(true);
    setCreateStatus("");
    try {
      const ownerArray = owners.split(',').map(s => s.trim()).filter(Boolean);
      const res = await postWithQuery('/api/factory/create', { 
        name: createName, 
        owners: ownerArray, 
        required 
      });

      if (res.result === 'success') {
        setCreateStatus(`Wallet created! Address: ${res.address}`);
      } else {
        setCreateStatus("Failed to create wallet.");
      }
    } catch (e) {
      setCreateStatus("Error creating wallet.");
    }
    setCreateLoading(false);
  };

  const handleAction = async (action: 'submit' | 'approve' | 'revoke' | 'execute') => {
    setInteractLoading(true);
    setInteractStatus("");
    try {
      let params: any = { address: walletAddr };
      if (action === 'submit') {
        params = { ...params, to, value, data };
      } else {
        params = { ...params, txId };
      }

      const res = await postWithQuery(`/api/wallet/${action}`, params);
      if (res.result === 'success') {
        setInteractStatus(`${action.charAt(0).toUpperCase() + action.slice(1)} successful! ${res.txId !== undefined ? 'TxID: ' + res.txId : ''}`);
      } else {
        setInteractStatus(`${action} failed. ${res.message || ''}`);
      }
    } catch (e) {
      setInteractStatus("Network error.");
    }
    setInteractLoading(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex p-1 bg-slate-100 rounded-lg w-fit">
        <button 
          onClick={() => setTab('create')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${tab === 'create' ? 'bg-white shadow text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}
        >
          Create Wallet
        </button>
        <button 
          onClick={() => setTab('interact')}
          className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${tab === 'interact' ? 'bg-white shadow text-slate-900' : 'text-slate-500 hover:text-slate-700'}`}
        >
          Manage Wallet
        </button>
      </div>

      {tab === 'create' ? (
        <Card title="New MultiSig Wallet" icon={Shield}>
          <div className="space-y-4">
            <Input label="Wallet Name" value={createName} onChange={(e: any) => setCreateName(e.target.value)} />
            <Input label="Owners (comma separated addresses)" placeholder="0x123..., 0x456..." value={owners} onChange={(e: any) => setOwners(e.target.value)} />
            <Input label="Required Confirmations" type="number" value={required} onChange={(e: any) => setRequired(e.target.value)} />

            <div className="pt-2">
              <Button onClick={handleCreate} isLoading={createLoading}>Deploy Wallet</Button>
            </div>
            {createStatus && <div className="text-sm font-medium text-indigo-600 mt-2">{createStatus}</div>}
          </div>
        </Card>
      ) : (
        <Card title="Manage Wallet Transactions" icon={Key}>
          <div className="space-y-6">
            <Input label="MultiSig Wallet Contract Address" value={walletAddr} onChange={(e: any) => setWalletAddr(e.target.value)} placeholder="0x..." />

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-4 p-4 border border-slate-100 rounded-xl bg-slate-50">
                <h3 className="font-semibold text-slate-900">Submit Transaction</h3>
                <Input label="To Address" value={to} onChange={(e: any) => setTo(e.target.value)} placeholder="0x..." />
                <Input label="Value (Wei)" value={value} onChange={(e: any) => setValue(e.target.value)} />
                <Input label="Data (Bytes)" value={data} onChange={(e: any) => setData(e.target.value)} />
                <Button variant="secondary" onClick={() => handleAction('submit')} isLoading={interactLoading} className="w-full">Submit</Button>
              </div>

              <div className="space-y-4 p-4 border border-slate-100 rounded-xl bg-slate-50">
                <h3 className="font-semibold text-slate-900">Existing Transaction</h3>
                <Input label="Transaction ID" value={txId} onChange={(e: any) => setTxId(e.target.value)} />
                <div className="flex gap-2">
                  <Button variant="primary" onClick={() => handleAction('approve')} isLoading={interactLoading} className="flex-1">Approve</Button>
                  <Button variant="danger" onClick={() => handleAction('revoke')} isLoading={interactLoading} className="flex-1">Revoke</Button>
                </div>
                <Button variant="secondary" onClick={() => handleAction('execute')} isLoading={interactLoading} className="w-full">Execute</Button>
              </div>
            </div>
            {interactStatus && <div className="text-center font-medium text-slate-700 mt-2">{interactStatus}</div>}
          </div>
        </Card>
      )}
    </div>
  );
};

// --- Main App ---

const App = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'transfer' | 'identity' | 'multisig'>('dashboard');

  const tabs = [
    { id: 'dashboard', label: 'ART Token', icon: Wallet },
    { id: 'transfer', label: 'Transfer', icon: Send },
    { id: 'identity', label: 'Identity (DID)', icon: User },
    { id: 'multisig', label: 'MultiSig Wallet', icon: Shield },
  ];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-white border-r border-slate-200 fixed md:relative h-auto md:h-screen z-10 hidden md:block">
        <div className="p-6 border-b border-slate-100">
          <div className="flex items-center gap-3 text-indigo-600">
            <Activity className="w-8 h-8" />
            <span className="text-xl font-bold tracking-tight text-slate-900">ART Token</span>
          </div>
        </div>
        <nav className="p-4 space-y-1">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-all ${
                activeTab === tab.id 
                  ? "bg-indigo-50 text-indigo-700 shadow-sm ring-1 ring-indigo-200" 
                  : "text-slate-600 hover:bg-slate-50 hover:text-slate-900"
              }`}
            >
              <tab.icon size={18} />
              {tab.label}
            </button>
          ))}
        </nav>
        <div className="p-4 mt-auto">
          <div className="bg-amber-50 text-amber-800 text-xs p-3 rounded-lg border border-amber-200 flex flex-col gap-2">
            <div className="flex items-center gap-2 font-semibold">
              <Server size={14} />
              Demo Mode Active
            </div>
            <p>Backend calls are being simulated in the browser.</p>
          </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white border-b border-slate-200 z-10 p-4 flex items-center gap-3 shadow-sm justify-between">
        <div className="flex items-center gap-3">
          <Activity className="w-6 h-6 text-indigo-600" />
          <span className="font-bold text-lg">ART Token</span>
        </div>
        <div className="bg-amber-100 text-amber-800 text-[10px] px-2 py-1 rounded-full font-bold uppercase">
          Demo Mode
        </div>
      </div>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 pt-20 md:pt-8 max-w-5xl mx-auto w-full">
        <header className="mb-8">
          <h1 className="text-2xl font-bold text-slate-900">
            {tabs.find(t => t.id === activeTab)?.label}
          </h1>
          <p className="text-slate-500 mt-1">Manage your crypto assets and identity securely.</p>
        </header>

        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && <Dashboard />}
          {activeTab === 'transfer' && <Transfer />}
          {activeTab === 'identity' && <Identity />}
          {activeTab === 'multisig' && <MultiSig />}
        </div>
      </main>

      {/* Mobile Nav */}
      <nav className="md:hidden fixed bottom-0 w-full bg-white border-t border-slate-200 flex justify-around p-2 z-20 pb-safe shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1 p-2 rounded-lg text-xs font-medium w-full ${
              activeTab === tab.id ? "text-indigo-600" : "text-slate-400"
            }`}
          >
            <tab.icon size={20} strokeWidth={activeTab === tab.id ? 2.5 : 2} />
            {tab.label}
          </button>
        ))}
      </nav>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(
  <ErrorBoundary>
    <App />
  </ErrorBoundary>
);

