          A\Wallet
        </h1>
        <p className="text-xs text-zinc-500 mt-1">Identity-Native Wallet</p>
      </div>

      <nav className="flex-1 p-4 space-y-2">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-none border-l-2 transition-all duration-200 ${
                isActive 
                  ? 'border-white bg-zinc-900 text-white' 
                  : 'border-transparent text-zinc-500 hover:text-zinc-300 hover:bg-zinc-900/50'
              }`}
            >
              <Icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-zinc-800">
        <button 
          onClick={disconnect}
          className="w-full flex items-center space-x-3 px-4 py-3 text-zinc-500 hover:text-white hover:bg-zinc-900 rounded-lg transition-colors"
        >
          <LogOut size={20} />
          <span>Disconnect</span>
        </button>
      </div>
    </div>
  );
};

