interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Simple Error Boundary for React 19 compliance
class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false
  };

  static getDerivedStateFromError(_: Error): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return <div className="p-8 text-red-500">Critical Error: App Crashed. Check Console.</div>;
    }
    return this.props.children;
  }
}

const App: React.FC = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');

  // App State simulating Blockchain State
  const [user, setUser] = useState<User>(INITIAL_USER);
  const [tokens, setTokens] = useState<Token[]>(INITIAL_TOKENS);
  const [proposals, setProposals] = useState<Proposal[]>(INITIAL_PROPOSALS);
  const [activities, setActivities] = useState<Activity[]>([]);

  // Simulate Connecting to WalletConnect / MetaMask
  const handleConnect = () => {
    setIsConnecting(true);
    setTimeout(() => {
      setIsConnected(true);
      setIsConnecting(false);
      setActiveTab('dashboard');
    }, 1500);
  };

  // 1. Register DID
  const handleRegisterDID = async () => {
      const newDID = await registerDID(user.address);
      setUser(prev => ({ ...prev, did: newDID }));
      const newActivity: Activity = {
          id: Date.now().toString(),
          type: 'Approval',
          detail: `Registered new DID: ${newDID}`,
          timestamp: new Date().toISOString()
      };
      setActivities([newActivity, ...activities]);
  };

  // 2. Buy with Stripe (Mock)
  const handleAddFunds = (amount: number, symbol: string) => {
    setTokens(prev => prev.map(t => 
      t.symbol === symbol ? { ...t, balance: t.balance + amount } : t
    ));
    const newActivity: Activity = {
      id: Date.now().toString(),
      type: 'Mint',
      detail: `Purchased ${amount} ${symbol} via Stripe`,
      timestamp: new Date().toISOString()
    };
    setActivities([newActivity, ...activities]);
  };

  // 3. Send to DID
  const handleSend = async (to: string, amount: number, symbol: string) => {
    // Optimistic Update
    setTokens(prev => prev.map(t => 
      t.symbol === symbol ? { ...t, balance: t.balance - amount } : t
    ));
    const newActivity: Activity = {
      id: Date.now().toString(),
      type: 'Transfer',
      detail: `Sent ${amount} ${symbol} to ${to.startsWith('did:') ? 'DID' : 'Addr'}...`,
      timestamp: new Date().toISOString()
    };
    setActivities([newActivity, ...activities]);
  };

  // 4. Deploy Multisig
  const handleDeployMultisig = async (owners: string[], threshold: number) => {
      const address = await deployMultisig(owners, threshold);
      const newActivity: Activity = {
          id: Date.now().toString(),
